import XCTest
@testable import ReaderCore

final class IdentityTests: XCTestCase {
    let identity = DocumentIdentity()

    /// xorshift32 byte stream; MUST match `gen()` in scripts/partial_md5_reference.py.
    static func generate(count: Int) -> Data {
        var out = [UInt8](repeating: 0, count: count)
        var s: UInt32 = 0x12345678
        for k in 0..<count {
            s ^= s << 13
            s ^= s >> 17
            s ^= s << 5
            out[k] = UInt8((s >> 8) & 0xFF)
        }
        return Data(out)
    }

    // Generated by `python3 scripts/partial_md5_reference.py --vectors`.
    static let vectors: [(Int, String)] = [
        (0, "d41d8cd98f00b204e9800998ecf8427e"),
        (100, "26d4c8c5b5f068772abc259fdc68676f"),
        (255, "a7cd0f1e4086a8da2c7c4fb7aa0119bc"),
        (256, "728a23f78bc1e78230a351f85b46d4a0"),
        (1024, "cf922a660a3911669581498f61600809"),
        (1025, "32146a844a1943192c72312f18eee75e"),
        (5000, "333f45d8f7383d082250329bd0279ae4"),
        (70000, "191afd2d92eb625696b0a5a10d317ae9"),
        (1048576, "f09cd1b3b75a1056a5b8bb91f1571cc6"),
        (20000000, "4bcb379a40e2a4f5b676e81587d2f52c"),
    ]

    func testPartialMD5DataVectors() {
        for (n, expected) in Self.vectors {
            XCTAssertEqual(identity.partialMD5(of: Self.generate(count: n)), expected, "size \(n)")
        }
    }

    func testPartialMD5FileVectors() throws {
        let dir = FileManager.default.temporaryDirectory.appendingPathComponent("idtests-\(UUID().uuidString)")
        try FileManager.default.createDirectory(at: dir, withIntermediateDirectories: true)
        defer { try? FileManager.default.removeItem(at: dir) }
        for (n, expected) in Self.vectors {
            let url = dir.appendingPathComponent("f\(n).bin")
            try Self.generate(count: n).write(to: url)
            XCTAssertEqual(try identity.partialMD5(fileAt: url), expected, "size \(n)")
        }
    }

    func testMissingFileThrows() {
        XCTAssertThrowsError(try identity.partialMD5(fileAt: URL(fileURLWithPath: "/nonexistent/x.epub"))) {
            XCTAssertEqual($0 as? IdentityError, .unreadableFile)
        }
    }

    // MARK: metaHash

    private func meta(_ title: String, _ authors: [String], _ ids: [(String?, String)] = []) -> BookMetadata {
        BookMetadata(title: title, authors: authors, identifiers: ids.map { BookIdentifier(scheme: $0.0, value: $0.1) })
    }

    // Expected values computed independently with Python hashlib over the NFC hash source.
    func testUUIDBeatsCalibreAndISBN() {
        let m = meta("Dune", ["Frank Herbert"], [
            (nil, "urn:isbn:9780441172719"), (nil, "calibre:42"),
            (nil, "urn:uuid:0b2c3d4e-0000-4000-8000-000000000001"),
        ])
        XCTAssertEqual(identity.hashSource(for: m), "Dune|Frank Herbert|0b2c3d4e-0000-4000-8000-000000000001")
        XCTAssertEqual(identity.metaHash(for: m), "366fb0a1c2858fe2fa8bec4f83d0b931")
    }

    func testCalibreBeatsISBN() {
        let m = meta("Dune", ["Frank Herbert"], [(nil, "urn:isbn:9780441172719"), (nil, "calibre:42")])
        XCTAssertEqual(identity.metaHash(for: m), "f0e1f587c2693d4df6dfce44ecd898c9")
    }

    func testISBNOnly() {
        let m = meta("Dune", ["Frank Herbert"], [(nil, "urn:isbn:9780441172719")])
        XCTAssertEqual(identity.metaHash(for: m), "90a8881b4edc9738d443e3b23a593dd7")
    }

    func testMultipleAuthors() {
        let m = meta("Good Omens", ["Terry Pratchett", " Neil Gaiman "], [(nil, "isbn:9780060853983")])
        XCTAssertEqual(identity.hashSource(for: m), "Good Omens|Terry Pratchett,Neil Gaiman|9780060853983")
        XCTAssertEqual(identity.metaHash(for: m), "751d48d5da3156d7ee71857a8c162c55")
    }

    func testUnicodeIsNFCNormalized() {
        let composed = meta("Caf\u{e9} \u{e0} Paris", ["Jos\u{e9} \u{c1}lvarez"])
        let decomposed = meta("Cafe\u{301} \u{e0} Paris", ["Jos\u{e9} \u{c1}lvarez"])
        XCTAssertEqual(identity.metaHash(for: composed), "e96ae6667f30a0b278a79d5f2a06df0e")
        XCTAssertEqual(identity.metaHash(for: decomposed), "e96ae6667f30a0b278a79d5f2a06df0e")
    }

    func testNoIdentifier() {
        XCTAssertEqual(identity.metaHash(for: meta("No Id", ["Anon"])), "b4cfec18d5389c30e870066d2767f80a")
        XCTAssertEqual(identity.metaHash(for: meta("T", [])), "5ede26c6cd8083fde992fe8069f66fd7")
    }

    func testNoPreferredSchemeJoinsAllNormalized() {
        let m = meta("Dune", ["Frank Herbert"], [(nil, "urn:foo:9780441172719"), (nil, "abc")])
        XCTAssertEqual(identity.hashSource(for: m), "Dune|Frank Herbert|9780441172719,abc")
        XCTAssertEqual(identity.metaHash(for: m), "7f2200aeafa59f044cde63bff1c9c69c")
    }

    func testNormalizeIdentifier() {
        XCTAssertEqual(DocumentIdentity.normalizeIdentifier("urn:uuid:abc"), "abc")
        XCTAssertEqual(DocumentIdentity.normalizeIdentifier("calibre:42"), "42")
        XCTAssertEqual(DocumentIdentity.normalizeIdentifier("a:b:c"), "b:c")
        XCTAssertEqual(DocumentIdentity.normalizeIdentifier("plain"), "plain")
    }
}
